WITH filtered AS (SELECT *, CASE WHEN firmware = '2.0.1' THEN 1 ELSE 0 END AS is_2_0_1 FROM device_readings WHERE TO_DATE(reading_ts) >= '2023-03-01'), flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 20 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM filtered), sessions_device_readings AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, status_bits, firmware, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT island_id, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, COUNT_IF(device_code = 'DV-01') AS dv_01_events, MIN(reading_ts) AS started_at, MAX(island_id) AS max_island_id FROM sessions_device_readings GROUP BY island_id;
